def admissible (U : Config G n) (b : Finset ℕ) :=
  (b : Set ℕ).Pairwise (fun i j => Disjoint (A.forced i).support (A.forced j).support) ∧
  b.biUnion (fun i => (A.forced i).inventory) = flags p.threshold U

def supBounds (o : Site n) (P : Support n) (F : Config G n → X) (c : ℝ) : Prop :=
    0 ≤ c ∧ ∀ U, Healthy p.threshold P U → ∀ l, List.length l ≤ p.order →
      (∀ A ∈ l, p.dirBound o A) → ‖leftDerivs F l U‖ ≤ c

def EBound (budget : ℝ) := ∃ b : ℕ → ℝ,
  (∀ i, p.supBounds (A.reg i).site (A.reg i).support (A.E i) (b i)) ∧
  ∀ x : Site n, SumBudget (fun i => if (A.reg i).site = x then p.mass (A.reg i).support (b i) else 0) budget

def KBound (budget : ℝ) := ∃ b : ℕ → ℝ,
  (∀ i, (0 ≤ b i) ∧ ∀ U, ‖A.K i U‖ ≤ b i) ∧
  ∀ x : Site n, SumBudget (fun i => if x ∈ (A.forced i).support then p.mass (A.forced i).support (b i) else 0) budget

def initial (C : SectionData F) (H : RG.History G) (N p : ℕ) (v : F.Coeff)
    (o : Site (H.S.side N p)) : Config G (H.S.side N p) → ℂ :=
  ((H.S.a N : ℂ)^d)⁻¹ • C.places (F.scaled (H.levels.clock.threshold N)⁻¹ v) o

def deltas (t:ℝ): List ι → ((ι→ℂ) →ₗ[ℂ] (ι→ℂ))
  | [] => LinearMap.id
  | i::l=> (delta i t).comp (deltas t l)

def conj (d : ℕ) : S.Field d →ₛₗ[starRingEnd ℂ] S.Field d :=
  (S.null d).liftQ ((S.project d).comp (L.bar d)) fun _ hx =>
    (Submodule.Quotient.mk_eq_zero _).mpr (S.real_null H d hx)

def mirror (d : ℕ) (s : Signed) : S.Field d →ₗ[ℂ] S.Field d :=
  (S.null d).liftQ ((S.project d).comp (L.mirrorGroup d s)) fun _ hx =>
    (Submodule.Quotient.mk_eq_zero _).mpr (S.move_null H s d hx)

def addresses (d : ℕ) : (freeTable F).Field d ≃ₗ[ℂ] (shellSector G d) ⧸ residual G d :=
  (Submodule.quotEquivOfEq _ _ (exactKer F d).symm).trans <|
    (collapsed F d).quotKerEquivOfSurjective ((residual G d).mkQ_surjective.comp (full F d))

def shellGrad (χ : E4 → ℝ) (b : Axis) (x : Points (n+1)) (q : Fin n → S.Tag) (B : S.Field d) :=
  - ∑ a : Axis, ∫ y : E4, ((Analysis.D (basis a) χ y : ℝ) : ℂ) *
    S.useAt T (Points.cons y x) (Fin.cons ⟨4,J a b⟩ (Fin.cons ⟨d,B⟩ q))

def shellSpin (χ : E4 → ℝ) (g : Ortho.Skew) (x : Points (n+1)) (q : Fin n → S.Tag) (B : S.Field d) :=
  - ∑ a : Axis, ∑ b : Axis, ∫ y : E4, ((Analysis.D (basis a) χ y * M4.move g.val (y - x 0) b : ℝ) : ℂ) *
    S.useAt T (Points.cons y x) (Fin.cons ⟨4,J a b⟩ (Fin.cons ⟨d,B⟩ q))

def RawTensor (H : S.RealSpin) (J : S.Stress) :=
  ∀ k a b, S.mirror H 4 k (J a b) = ∑ i : Axis, ∑ j : Axis,
    (((k.matrix i a * k.matrix j b : ℝ) : ℂ)) • J i j

def Oriented (T : Table L) :=
  ∀ n (v : Fin n → S.Tag), ∀ x ∈ conf n, ∀ K : Ortho,
    S.useAt T (Points.move K x) (R.label K ∘ v) = S.useAt T x v

def freeWithStress (v : Labels.Frames G) {n : ℕ} (q : Slots n → (freeTable v).Tag) (b : Slots n → Bool)
    (a : Slots n → Axis × Axis) (i : Slots n) : (freeTable v).Tag := if b i then
      ⟨4,freeStress v (a i).1 (a i).2⟩ else q i

def mixedTag {n : ℕ} (q : Slots n → (Bel C.book).Tag) (isJ : Slots n → Bool)
    (ab : Slots n → Axis × Axis) (T0 : (Bel C.book).Stress) (i : Slots n) : (Bel C.book).Tag :=
  if isJ i then ⟨4,T0 (ab i).1 (ab i).2⟩ else q i

def Mode.kernel (m : Mode) (r : ℝ) (p : Space) : ℝ :=
  let E := Real.sqrt ((m.mass:ℝ)^2 + ‖p‖^2)
  1 / (2*E) * E^m.timeOrder * m.numerator p * Real.exp (-r*E)

def timePair (r : ℝ) : Points 2 :=
  WithLp.toLp 2 fun i => WithLp.toLp 2 (Fin.snoc (fun _ : Fin 3 => (0:ℝ))
    (Fin.append (fun _ : Fin 1 => -(r/2)) (fun _ : Fin 1 => r/2) i))

def JointExistence : Prop := ∀ g : GaugeGroup, g.IsSimple → ∃ C : WilsonFamily g,
  WilsonRegularity C ∧ ∀ p : ℕ → ℕ, StrictMono p → ∃ q : ℕ → ℕ, StrictMono q ∧
    ∃ T : Hierarchy C, T.Properties (p ∘ q)

volume m i :
  let j := a.clock.J (m+1)
  W.shells j * (1+a.clock.coverSize m+a.clock.coverSize (m+1))^(W.growth j) ≤ (a.S.side m i).val

def entry {S : Finset Cover} (U : CoverConfig G) (k : Index G S) :=
  let z := G.mat (U k.1.val) k.2.1 k.2.2.1
  if k.2.2.2 then star z else z

def facesum (U : CoverConfig G) : ℝ :=
  ∑ x : P.Points, ∑ p : PlaqAxes,
    if (∀ y ∈ visits x.val (square p.val.1 p.val.2), y ∈ P.sites)
    then G.chord (faceValue U (x.val,p)) else 0

def cant (U : Config G n) : BaseSites G n →L[ℝ] Link G n :=
    edgeColor.symm.toContinuousLinearMap ∘L (ContinuousLinearMap.pi fun e : Edge (Site n) =>
      ContinuousLinearMap.proj (φ:=fun _ : Site n => G.Color) e.1 - (G.adjoint (U e)).toContinuousLinearMap ∘L ContinuousLinearMap.proj (φ:=fun _ : Site n => G.Color) (e.1+step e.2)) ∘L gaugeColor.toContinuousLinearMap

def thinned (A : Clip) (t : ℝ) (d R : ℕ) (U : Config G n) (x : Twin n) : G.Color :=
    if x.2 then if PathData.kept A t x.1.1 U then shorten S R d U x.1 else 0 else
        (if toll U x.1=0 then 1 else min 1 (t/toll U x.1)) • shoot A U x.1

def workF (U : Config G f) (V : Config G c) (t s : ℝ) (x : Cell f) :=
    crown T.up T.high R 1 t U x + ∑ i : Bool,
      (‖T.Mv R s V (x,i)‖^2/2 - inner ℝ (T.Mv R s V (x,i)) (T.Xf R U (x,i)))

def workC (V : Config G c) (s : ℝ) (x : Cell c) :=
    (∑ i : Bool, (inner ℝ (T.vision R s V (x,i)) (T.Xn R V (x,i)) - ‖T.vision R s V (x,i)‖^2/2)) -
      crown T.down T.low R S.patch.L.val s V x

def workD (V : Config G c) (s : ℝ) (x : Cell c) :=
    ∑ i : Bool, inner ℝ (T.vision R s V (x,i)) (T.vision R s V (x,i) -
      (unzip (T.Φ R V) (T.Mv R s V) (x,i) + unzip (T.Φ' R V) (T.Mw R s V) (x,i) + unzip (T.N R V) (zip (T.N R V) (T.vision R s V)) (x,i)))/2

def scalp (B : Finset (Bond f)) (X : Coat T F) (C : Config G c) (β d : ℝ) (w : Air f G) :=
    let S:= lensS B G; let x := Pond.swim S w
    let g:= Pond.swim S (course X d β w C)
    jacL B X d β C w * (lens₀ (circuit S (vary X C).relating) g / lens₀ (circuit S X.relating) x)

def recoil (B : Finset (Bond f)) (X : Coat T F) (C : Config G c) (d : ℝ) (Ñ : ChartRatio G) (p : Molecule S) (R : Rep G f)
    (W a : ℝ) (l : ℕ) (y : Air f G) :=
    scalp B X C R.beta d y * Polar.floating (vary X C) a R W Ñ (course X d R.beta y C) (own p) l p

def principal (c : Clip) (p : BudgetPoint) (β : ℝ) (U : Config G n) : ℝ :=
